import {MAP} from '../map.js';
import {P} from './palette.js';
import {oval,star} from './shapes.js';
const flights=new Set();
export function animateSunCollection(drop,field,hud,automatic=false){if(globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;while(flights.size>=18){const oldest=flights.values().next().value;oldest.remove();flights.delete(oldest)}const r=field.getBoundingClientRect(),h=hud.getBoundingClientRect(),x=r.left+drop.x/MAP.cols*r.width,y=r.top+drop.y/MAP.rows*r.height,tx=h.left+h.width/2,ty=h.top+h.height/2,el=document.createElement('canvas');el.width=72;el.height=72;el.className='sun-flight-art';el.style.left=x-18+'px';el.style.top=y-18+'px';const c=el.getContext('2d');c.translate(36,36);for(let i=0;i<8;i++){const a=i*Math.PI/4;star(c,Math.cos(a)*20,Math.sin(a)*20,6,P.sun,a)}oval(c,0,0,17,17,P.sun);oval(c,-5,-6,7,4,P.cream,false);for(const [px,py] of [[-28,26],[-21,32],[-32,12]])star(c,px,py,3,P.critical);document.body.append(el);flights.add(el);const dx=tx-x,dy=ty-y;const animation=el.animate([{transform:'translate(0,0) scale(1.2,.75)',opacity:1},{transform:'translate('+(dx*.18)+'px,'+(dy*.18-35)+'px) scale(1.1)',opacity:1,offset:.3},{transform:'translate('+dx+'px,'+dy+'px) scale(.25)',opacity:0}],{duration:automatic?650:520,easing:'cubic-bezier(.4,0,.25,1)',fill:'forwards'});animation.onfinish=()=>{el.remove();flights.delete(el)};animation.oncancel=()=>{el.remove();flights.delete(el)}}
